import './zodConfig';
import { z } from 'zod';
import {
  COLOR_IDS,
  HIGHLIGHT_KINDS,
  MAX_BANK_NAME_CHARS,
  MAX_COMMENT_CHARS,
  MAX_CONTEXT_CHARS,
  MAX_HEADING_CHARS,
  MAX_QUOTE_CHARS,
  MAX_TITLE_CHARS,
  MAX_URL_CHARS,
  PDF_TEXT_ALGORITHM,
  SCHEMA_VERSION,
  TEXT_ALGORITHM,
} from './constants';
import { DENY_HOST, parseHttpUrl } from './urls';

/** Sortable opaque identifier (UUIDv7 generated by the storage layer). Validation is deliberately loose. */
export const Id = z.string().regex(/^[0-9A-Za-z_-]{8,64}$/, 'invalid id');
export const IsoDate = z.iso.datetime();
export const HttpUrl = z.url({ protocol: /^https?$/ }).max(MAX_URL_CHARS);

export const HighlightKind = z.enum(HIGHLIGHT_KINDS);
export const ColorId = z.enum(COLOR_IDS);
export const Priority = z.number().int().min(1).max(5);
/**
 * How a highlight came to be: a capture gesture, or 'import' for highlights read from a Markdown, CSV,
 * Anki text, Word, PowerPoint, EPUB or HTML file (their `customFields` say which file and place,
 * and that they still need review).
 */
export const CaptureMethod = z.enum(['toolbar', 'shortcut', 'context-menu', 'import']);
export const ResolveStatus = z.enum(['unchecked', 'resolved', 'changed', 'ambiguous', 'orphaned']);

export type Id = z.infer<typeof Id>;
export type HighlightKind = z.infer<typeof HighlightKind>;
export type ColorId = z.infer<typeof ColorId>;
export type Priority = z.infer<typeof Priority>;
export type CaptureMethod = z.infer<typeof CaptureMethod>;
export type ResolveStatus = z.infer<typeof ResolveStatus>;

const recordMeta = {
  schemaVersion: z.literal(SCHEMA_VERSION),
  createdAt: IsoDate,
  updatedAt: IsoDate,
  deletedAt: IsoDate.nullable(),
};

// ---------------------------------------------------------------------------------------------
// Anchors (W3C Web Annotation inspired). Offsets are in the sv-text-v1 stream, not raw DOM text.
// ---------------------------------------------------------------------------------------------

export const TextQuoteSelector = z.object({
  exact: z.string().min(1).max(MAX_QUOTE_CHARS),
  prefix: z.string().max(MAX_CONTEXT_CHARS),
  suffix: z.string().max(MAX_CONTEXT_CHARS),
});

export const TextPositionSelector = z
  .object({ start: z.number().int().min(0), end: z.number().int().min(1) })
  .refine((p) => p.end > p.start, 'end must be after start');

export const HtmlAnchorSet = z.object({
  type: z.literal('html'),
  textAlgorithm: z.literal(TEXT_ALGORITHM),
  textQuote: TextQuoteSelector,
  textPosition: TextPositionSelector,
  /** Hint only. Never authoritative: DOM structure changes freely between visits. */
  structuralPath: z.string().max(1024).nullable(),
  /** Non-cryptographic hash of the whole document text stream at capture time (change detection). */
  contentSignature: z.string().max(32),
  /** Length of the text stream at capture time. */
  documentTextLength: z.number().int().min(0),
});
export type HtmlAnchorSet = z.infer<typeof HtmlAnchorSet>;

/** Normalised rectangle on a PDF page: 0..1 of the page box, origin top-left, rotation 0. */
export const PdfRect = z.object({
  x: z.number().min(0).max(1),
  y: z.number().min(0).max(1),
  w: z.number().min(0).max(1),
  h: z.number().min(0).max(1),
});
export type PdfRect = z.infer<typeof PdfRect>;

/**
 * Anchor inside the extension-owned PDF reader (ADR-006). Field names that overlap HtmlAnchorSet
 * (textQuote, textPosition, contentSignature, documentTextLength) keep their meaning but refer to
 * the page text stream of ONE page, so generic code (duplicate detection, ordering) works on both.
 */
export const PdfAnchorSet = z.object({
  type: z.literal('pdf'),
  textAlgorithm: z.literal(PDF_TEXT_ALGORITHM),
  /** Content fingerprint of the document (sha-256 hex of the bytes, or PDF.js fingerprint fallback). */
  documentFingerprint: z.string().min(8).max(128),
  /** 1-based page number. */
  pageNumber: z.number().int().min(1),
  /** Page rotation (degrees, 0/90/180/270) when the rects were captured. */
  rotation: z.number().int(),
  /** Highlight rectangles, one per selected line box, in reading order. */
  rects: z.array(PdfRect).min(1).max(256),
  textQuote: TextQuoteSelector,
  /** Offsets within this page's text stream. */
  textPosition: TextPositionSelector,
  contentSignature: z.string().max(32),
  /** Length of the page text stream at capture time. */
  documentTextLength: z.number().int().min(0),
});
export type PdfAnchorSet = z.infer<typeof PdfAnchorSet>;

export const AnchorSet = z.discriminatedUnion('type', [HtmlAnchorSet, PdfAnchorSet]);
export type AnchorSet = z.infer<typeof AnchorSet>;

// ---------------------------------------------------------------------------------------------
// Persisted records
// ---------------------------------------------------------------------------------------------

export const Bank = z.object({
  id: Id,
  ...recordMeta,
  name: z.string().trim().min(1).max(MAX_BANK_NAME_CHARS),
  color: ColorId,
  position: z.number(),
  isInbox: z.boolean(),
});
export type Bank = z.infer<typeof Bank>;

export const Source = z.object({
  id: Id,
  ...recordMeta,
  /** 'pdf' sources are keyed by `documentId` (urlKey is `pdf:<documentId>`), see packages/storage. */
  type: z.enum(['web', 'pdf']),
  /** Set for type 'pdf': id of the `documents` row (content fingerprint of the file). */
  documentId: Id.optional(),
  /** Normalised identity of the page (canonical URL when trustworthy, else the page URL). */
  urlKey: z.string().max(MAX_URL_CHARS),
  /** Normalised URL the user actually visited; secondary lookup key. */
  visitedKey: z.string().max(MAX_URL_CHARS),
  originalUrl: HttpUrl,
  canonicalUrl: HttpUrl.nullable(),
  host: z.string().max(253),
  title: z.string().max(MAX_TITLE_CHARS),
});
export type Source = z.infer<typeof Source>;

/** User-defined metadata on a highlight (PRD "Custom fields"). Keys and values are plain text/numbers. */
export const MAX_CUSTOM_FIELDS = 32;
export const MAX_CUSTOM_FIELD_KEY_CHARS = 64;
export const MAX_CUSTOM_FIELD_VALUE_CHARS = 500;

export const CustomFieldKey = z
  .string()
  .min(1)
  .max(MAX_CUSTOM_FIELD_KEY_CHARS)
  .refine(
    (key) =>
      key === key.trim() &&
      key !== '__proto__' &&
      ![...key].some((ch) => ch.charCodeAt(0) < 0x20 || ch.charCodeAt(0) === 0x7f),
    'invalid custom field name',
  );
export const CustomFieldValue = z.union([
  z.string().max(MAX_CUSTOM_FIELD_VALUE_CHARS),
  z.number(),
  z.boolean(),
]);
export const CustomFields = z
  .record(CustomFieldKey, CustomFieldValue)
  .refine((r) => Object.keys(r).length <= MAX_CUSTOM_FIELDS, `at most ${MAX_CUSTOM_FIELDS} fields`);
export type CustomFields = z.infer<typeof CustomFields>;

export const Highlight = z.object({
  id: Id,
  ...recordMeta,
  sourceId: Id,
  /** Immutable source provenance. Never edited after capture; user interpretation goes in userComment. */
  exactQuote: z.string().min(1).max(MAX_QUOTE_CHARS),
  normalizedQuote: z.string().max(MAX_QUOTE_CHARS),
  quoteHash: z.string().length(64),
  anchorSet: AnchorSet,
  kind: HighlightKind,
  color: ColorId,
  priority: Priority,
  userComment: z.string().max(MAX_COMMENT_CHARS),
  headingContext: z.string().max(MAX_HEADING_CHARS).nullable(),
  captureMethod: CaptureMethod,
  capturedAt: IsoDate,
  resolveStatus: ResolveStatus,
  resolveConfidence: z.number().min(0).max(1).nullable(),
  lastResolvedAt: IsoDate.nullable(),
  /**
   * Immutable provenance of the capture: the address (credentials removed) and title of the page
   * as it was when the quote was saved. A Source can span address variants; this does not. Absent
   * on rows written before these existed. Not indexed, so no Dexie version bump.
   */
  capturedUrl: HttpUrl.optional(),
  capturedTitle: z.string().max(MAX_TITLE_CHARS).optional(),
  /** User metadata (modality, system, exam frequency ...). Never part of the immutable provenance. */
  customFields: CustomFields.optional(),
});
export type Highlight = z.infer<typeof Highlight>;

/** Many-to-many membership so one highlight can live in several banks without duplication. */
export const HighlightBank = z.object({
  highlightId: Id,
  bankId: Id,
  /** Reserved for the Phase 2 folder hierarchy. Always null in schema v1. */
  folderId: Id.nullable(),
  addedAt: IsoDate,
});
export type HighlightBank = z.infer<typeof HighlightBank>;

// ---------------------------------------------------------------------------------------------
// Views passed across the message boundary (never raw DB rows to untrusted contexts)
// ---------------------------------------------------------------------------------------------

export const HighlightView = z.object({
  id: Id,
  sourceId: Id,
  exactQuote: z.string(),
  anchorSet: AnchorSet,
  kind: HighlightKind,
  color: ColorId,
  priority: Priority,
  userComment: z.string(),
  headingContext: z.string().nullable(),
  bankIds: z.array(Id),
  capturedAt: IsoDate,
  resolveStatus: ResolveStatus,
  resolveConfidence: z.number().nullable(),
});
export type HighlightView = z.infer<typeof HighlightView>;

export const PageInfo = z.object({
  url: HttpUrl,
  canonicalUrl: HttpUrl.nullable(),
  title: z.string().max(MAX_TITLE_CHARS),
});
export type PageInfo = z.infer<typeof PageInfo>;

// ---------------------------------------------------------------------------------------------
// Organisation records (Dexie v4, docs/adr/011-schema-v4.md): auto-filing rules, syllabi, relations.
// Same envelope as every record above (schemaVersion, createdAt, updatedAt, deletedAt).
// ---------------------------------------------------------------------------------------------

export const MAX_FILING_RULES = 200;
/** Values per match field of one rule. */
export const MAX_FILING_MATCH_VALUES = 20;
export const MAX_FILING_RULE_NAME_CHARS = 80;
/** Characters of one `titleContains` / `quoteContains` value. */
export const MAX_FILING_TEXT_CHARS = 200;
export const MAX_FILING_TAG_IDS = 20;

/** A lower-case host name, without scheme, port or path. Matches the host and every subdomain. */
const FilingHost = z
  .string()
  .min(1)
  .max(253)
  .regex(DENY_HOST, 'use a lower-case host name such as example.com, without https:// or a path');
/** An http(s) address, without credentials, that an address must start with. */
const FilingUrlPrefix = z
  .string()
  .min(1)
  .max(MAX_URL_CHARS)
  .refine((value) => {
    const url = parseHttpUrl(value);
    return url !== null && url.username === '' && url.password === '';
  }, 'use an http(s) address without a user name or password');
const FilingText = z.string().trim().min(1).max(MAX_FILING_TEXT_CHARS);
const filingList = <T extends z.ZodType>(item: T, max = MAX_FILING_MATCH_VALUES) =>
  z.array(item).max(max).optional();

/**
 * What a rule looks at. Fields are ANDed; the values inside one field are ORed; a field that is
 * absent or empty is not a condition; a match with no condition at all never matches (see
 * `matchFilingRules` in filing.ts, which is the one place the semantics live).
 */
export const FilingRuleMatch = z.object({
  hosts: filingList(FilingHost),
  urlPrefixes: filingList(FilingUrlPrefix),
  titleContains: filingList(FilingText),
  quoteContains: filingList(FilingText),
  tagIds: filingList(Id, MAX_FILING_TAG_IDS),
  kinds: filingList(HighlightKind, HIGHLIGHT_KINDS.length),
  sourceTypes: filingList(z.enum(['web', 'pdf']), 2),
});
export type FilingRuleMatch = z.infer<typeof FilingRuleMatch>;

export const FilingRuleAction = z.object({
  bankId: Id,
  folderId: Id.nullable().optional(),
  addTagIds: filingList(Id, MAX_FILING_TAG_IDS),
});
export type FilingRuleAction = z.infer<typeof FilingRuleAction>;

/**
 * An auto-filing rule. `order` is the rule's rank (ascending, the first matching rule wins the
 * placement); `requireConfirm` defaults to true so a rule never files silently unless the person
 * turned that on for it.
 */
export const FilingRule = z.object({
  id: Id,
  ...recordMeta,
  name: z.string().trim().min(1).max(MAX_FILING_RULE_NAME_CHARS),
  enabled: z.boolean(),
  order: z.number().int().min(0).max(1_000_000),
  match: FilingRuleMatch,
  action: FilingRuleAction,
  requireConfirm: z.boolean().default(true),
});
export type FilingRule = z.infer<typeof FilingRule>;

export const MAX_SYLLABUS_DEPTH = 6;
export const MAX_SYLLABUS_NODES = 500;
export const MAX_SYLLABI = 100;
export const MAX_SYLLABUS_NAME_CHARS = 120;
export const MAX_SYLLABUS_TITLE_CHARS = 200;
/** Banks and tags one node may point at. */
export const MAX_SYLLABUS_LINKS = 50;
export const MAX_SYLLABUS_WEIGHT = 1000;

export interface SyllabusNode {
  id: string;
  title: string;
  children: SyllabusNode[];
  /** Banks whose cards and highlights count towards this topic. */
  bankIds: string[];
  tagIds: string[];
  /** Relative importance (exam weighting); absent = equal share. */
  weight?: number;
}

/**
 * Built level by level instead of with a lazy self-reference: a hostile archive nested a million
 * deep fails here, at depth MAX_SYLLABUS_DEPTH, with a plain validation error, never by overflowing
 * the stack inside the parser.
 */
function syllabusNodeSchema(levels: number): z.ZodType<SyllabusNode> {
  const children = (levels <= 1
    ? z.array(z.never()).max(0)
    : z.array(syllabusNodeSchema(levels - 1))) as unknown as z.ZodType<SyllabusNode[]>;
  return z.object({
    id: Id,
    title: z.string().trim().min(1).max(MAX_SYLLABUS_TITLE_CHARS),
    children,
    bankIds: z.array(Id).max(MAX_SYLLABUS_LINKS),
    tagIds: z.array(Id).max(MAX_SYLLABUS_LINKS),
    weight: z.number().positive().max(MAX_SYLLABUS_WEIGHT).optional(),
  }) as unknown as z.ZodType<SyllabusNode>;
}
export const SyllabusNode = syllabusNodeSchema(MAX_SYLLABUS_DEPTH);

/** Pre-order walk without recursion. `depth` is 1 for the top level. */
export function flattenSyllabus(
  nodes: readonly SyllabusNode[],
): Array<{ node: SyllabusNode; depth: number; parentId: string | null }> {
  const out: Array<{ node: SyllabusNode; depth: number; parentId: string | null }> = [];
  const stack: Array<{ node: SyllabusNode; depth: number; parentId: string | null }> = [];
  for (let i = nodes.length - 1; i >= 0; i--) {
    stack.push({ node: nodes[i] as SyllabusNode, depth: 1, parentId: null });
  }
  while (stack.length > 0) {
    const item = stack.pop() as (typeof stack)[number];
    out.push(item);
    const kids = Array.isArray(item.node.children) ? item.node.children : [];
    for (let i = kids.length - 1; i >= 0; i--) {
      stack.push({ node: kids[i] as SyllabusNode, depth: item.depth + 1, parentId: item.node.id });
    }
  }
  return out;
}

/** Size, depth and repeated ids of a tree, for messages before (and checks after) validation. */
export function measureSyllabus(nodes: readonly SyllabusNode[]): {
  count: number;
  depth: number;
  duplicateIds: string[];
} {
  const seen = new Set<string>();
  const duplicateIds = new Set<string>();
  let depth = 0;
  const flat = flattenSyllabus(nodes);
  for (const { node, depth: d } of flat) {
    depth = Math.max(depth, d);
    if (seen.has(node.id)) duplicateIds.add(node.id);
    seen.add(node.id);
  }
  return { count: flat.length, depth, duplicateIds: [...duplicateIds] };
}

/**
 * A user-made outline of what an exam or course covers. Each node can point at banks and tags, which
 * is how coverage is computed (nothing is guessed from text).
 */
export const Syllabus = z
  .object({
    id: Id,
    ...recordMeta,
    name: z.string().trim().min(1).max(MAX_SYLLABUS_NAME_CHARS),
    nodes: z.array(SyllabusNode).max(MAX_SYLLABUS_NODES),
  })
  .superRefine((syllabus, ctx) => {
    const { count, duplicateIds } = measureSyllabus(syllabus.nodes);
    if (count > MAX_SYLLABUS_NODES) {
      ctx.addIssue({
        code: 'custom',
        path: ['nodes'],
        message: `a syllabus holds at most ${MAX_SYLLABUS_NODES} topics`,
      });
    }
    if (duplicateIds.length > 0) {
      ctx.addIssue({ code: 'custom', path: ['nodes'], message: 'topic ids must be unique' });
    }
  });
export type Syllabus = z.infer<typeof Syllabus>;

/** What a relation can connect: the three kinds of the person's own content. */
export const RELATION_ENTITY_KINDS = ['highlight', 'knowledgePoint', 'note'] as const;
export const RELATION_TYPES = [
  'related',
  'supports',
  'contradicts',
  'cause',
  'example',
  'prerequisite',
] as const;
export const MAX_RELATION_NOTE_CHARS = 500;
export const RelationEntityKind = z.enum(RELATION_ENTITY_KINDS);
export type RelationEntityKind = z.infer<typeof RelationEntityKind>;
export const RelationType = z.enum(RELATION_TYPES);
export type RelationType = z.infer<typeof RelationType>;

/**
 * A directed link `from -> to` made by the person. Never part of a highlight's provenance: it names
 * highlights, knowledge points and notes by id and cannot change what any of them says. The five
 * identity fields never change after creation (a different link is a different row).
 */
export const Relation = z
  .object({
    id: Id,
    ...recordMeta,
    fromKind: RelationEntityKind,
    fromId: Id,
    toKind: RelationEntityKind,
    toId: Id,
    type: RelationType,
    note: z.string().max(MAX_RELATION_NOTE_CHARS).optional(),
  })
  .refine((r) => !(r.fromKind === r.toKind && r.fromId === r.toId), {
    message: 'an item cannot be linked to itself',
  });
export type Relation = z.infer<typeof Relation>;
